Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to rewrite:
<original_code>
#include <bits/stdc++.h>
#define rep(i,n) for (int i = 0; i < n; i++)
using namespace std;
typedef long long ll;
typedef unsigned long long ull;
typedef pair<int, int> pi;
typedef pair<pi, pi> pp;
typedef pair<ll, ll> pl;
const double EPS = 1e-9;
const ll MOD = 1000000007;
const int inf = 1 << 30;
const ll linf = 1LL << 60;

struct edge{int to, cap, cost, rev; };

struct MIN_COST_FLOW {
    #define MAX_V 5010
    int V;
    vector<edge> G[MAX_V];
    int h[MAX_V];
    int dist[MAX_V];
    int prevv[MAX_V], preve[MAX_V];

    void init (int n) {
        V = n;
    }

    void add_edge(int from, int to, int cap, int cost){
        //cerr << from << " " << to << " " << cap << " " << cost << endl;
        G[from].push_back((edge){to, cap, cost, (int)G[to].size()});
        G[to].push_back((edge){from, 0, -cost, (int)G[from].size()-1});
    }

    int min_cost_flow(int s, int t, int f){
        int res = 0;
        fill(h, h+V, 0);
        while(f > 0){    
            priority_queue<pi, vector<pi>, greater<pi> > que;
            fill(dist, dist+V, inf);
            dist[s] = 0;
            que.push(pi(0,s));
            while(!que.empty()){
                pi p = que.top(); que.pop();
                int v = p.second;
                if(dist[v] < p.first) continue;
                for(int i = 0; i < G[v].size(); i++){
                    edge &e = G[v][i];
                    if(e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]){
                        dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        que.push(pi(dist[e.to],e.to));
                    }
                }
            }
            if(dist[t] == inf){
                return -1;
            }
            for(int v = 0; v < V; v++) h[v] += dist[v];

            int d = f;
            for(int v = t; v != s; v = prevv[v]){
                d = min(d, G[prevv[v]][preve[v]].cap);
            }
            f -= d;
            res += d*h[t];
            for(int v = t; v != s; v = prevv[v]){
                edge &e = G[prevv[v]][preve[v]];
                e.cap -= d;
                G[v][e.rev].cap += d;
            }
        }
        return res;
    }
};

MIN_COST_FLOW mcf;

int n, m, k, c, d;
int a[50];
int cnt[50];
vector<int> e[50];

const int T = 100;

int main() {
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    rep(i,k) scanf("%d", a+i);
    rep(i,k) cnt[a[i]-1]++;
    rep(i,m) {
        int x, y; scanf("%d%d", &x, &y);
        x--; y--;
        e[x].push_back(y);
        e[y].push_back(x);
    }
    mcf.init(n*T+2);
    rep(i,n) mcf.add_edge(n*T, i, cnt[i], 0);
    rep(i,T) mcf.add_edge(i*n, n*T+1, k, c*i);
    rep(i,n) {
        rep(j,T-1) mcf.add_edge(j*n+i, (j+1)*n+i, k, 0);
        for (int to: e[i]) {
            rep(j,T-1) {
                rep(u,k) {
                    int cost = (u+1)*(u+1)*d-u*u*d;
                    mcf.add_edge(j*n+i, (j+1)*n+to, 1, cost);
                }
            }
        }
    }
    printf("%d\n", mcf.min_cost_flow(n*T, n*T+1, k));
}

